package vn.boardinghub.config;import io.swagger.v3.oas.models.*;import io.swagger.v3.oas.models.info.*;import io.swagger.v3.oas.models.security.*;import org.springframework.context.annotation.*;
@Configuration public class OpenApiConfig{@Bean OpenAPI boardingHubApi(){return new OpenAPI().info(new Info().title("BoardingHub API").version("1.0.0").description("API quản lý phòng trọ và chi phí sinh hoạt chung")).addSecurityItem(new SecurityRequirement().addList("bearerAuth")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT")));}}
